# Measure the 10-byte run that contains the 0x60539e07 halfword.
# Static. No emulator. Do not edit this file after it has run.
import json
import struct
from pathlib import Path

BASE = 0x60021020
data = Path("inputs/00_0100_50000020.decoded.bin").read_bytes()
START = 0x60539DFF  # first record of the visible pair


def off(addr):
    return addr - BASE


def rec(addr):
    b = data[off(addr) : off(addr) + 10]
    ptr, mid, tail, key = struct.unpack_from("<IHHH", b)
    return b, ptr, mid, tail, key


rows = []
addr = START
while True:
    b, ptr, mid, tail, key = rec(addr)
    if ptr != 0xFAA32EE8 or tail != 0xFC00:
        break
    rows.append({"addr": f"{addr:#x}", "key_addr": f"{addr + 8:#x}", "mid": f"{mid:#x}", "key": f"{key:#x}"})
    addr += 10
    if len(rows) > 4000:
        break

# Walk backward from START.
back = []
addr = START - 10
while addr >= BASE:
    b, ptr, mid, tail, key = rec(addr)
    if ptr != 0xFAA32EE8 or tail != 0xFC00:
        break
    back.append({"addr": f"{addr:#x}", "key_addr": f"{addr + 8:#x}", "mid": f"{mid:#x}", "key": f"{key:#x}"})
    addr -= 10
    if len(back) > 4000:
        break
back.reverse()
all_rows = back + rows
keys = [int(r["key"], 16) for r in all_rows]
doc = {
    "record_bytes": 10,
    "constant_pointer": "0xfaa32ee8",
    "tail_halfword": "0xfc00",
    "count": len(all_rows),
    "first": all_rows[0] if all_rows else None,
    "last": all_rows[-1] if all_rows else None,
    "contains_key_0x5b82": 0x5B82 in keys,
    "key_min": f"{min(keys):#x}" if keys else None,
    "key_max": f"{max(keys):#x}" if keys else None,
    "key_step_set": sorted({keys[i + 1] - keys[i] for i in range(len(keys) - 1)})[:8],
    "around_5b82": [r for r in all_rows if int(r["key"], 16) in (0x5A82, 0x5B82, 0x5C82)],
}
Path("work/out/run-60539e07-t10.json").write_text(json.dumps(doc, indent=2) + "\n", encoding="utf-8")
print(f"count {doc['count']} first {doc['first']} last {doc['last']} has5b82 {doc['contains_key_0x5b82']}")
print("steps", doc["key_step_set"])
print("around", doc["around_5b82"])
